#!/usr/bin/env node
// Writes the reference pages generated from AUGUR's JSON schemas into src/content/docs/reference/schemas/,
// before every build, so they can't drift from what the code checks. The folder is git-ignored: the schemas
// are the source. The OpenAPI reference is generated by starlight-openapi (astro.config.mjs).
//
// node scripts/reference.mjs
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const repo = (path) => fileURLToPath(new URL(`../../${path}`, import.meta.url));
const out = fileURLToPath(new URL('../src/content/docs/reference/schemas/', import.meta.url));

/** The schemas the reference shows, in sidebar order. */
export const SCHEMAS = [
  {
    slug: 'app-manifest',
    title: 'App manifest',
    file: 'platform/packages/app-tools/manifest-3.schema.json',
    intro: "An app's `manifest.json`: what AUGUR's shell can know about the app before any of its code runs.",
  },
  {
    slug: 'score-part',
    title: 'Score part',
    file: 'platform/packages/app-tools/score-part-1.schema.json',
    intro: "AUGUR's rules for each of an app's `score/<part>.score.yaml` files, checked as well as Score's own schema.",
  },
  {
    slug: 'app-release',
    title: 'App release file',
    file: 'platform/packages/app-tools/app-release-2.schema.json',
    intro: 'The file an app release carries, and the only thing a deployment installs an app from.',
  },
];

/** Decision record numbers and internal spec references are for people working on AUGUR, not for readers. */
export const forReaders = (text = '') =>
  text
    .replace(/\s*\([^()]*\b(?:ADRs? \d|PDR-\d|decision \d|the spec\b)[^()]*\)/gi, '')
    .replace(/\s*Rules a schema cannot say are listed in the spec's section '[^']*'\./g, '')
    .replace(/\s+/g, ' ')
    .trim();

// Text from a schema is shown as text: a <id> in it is not an HTML tag, and a | doesn't end a table cell.
// Code spans (between backticks) are left as they are.
const cell = (text) =>
  forReaders(String(text))
    .split('`')
    .map((part, i) => (i % 2 ? part : part.replace(/</g, '&lt;')))
    .join('`')
    .replace(/\|/g, '\\|');
const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const code = (value) => `\`${typeof value === 'string' ? value : JSON.stringify(value)}\``;

/** A schema's type, in words. */
export const typeOf = (schema, defs) => {
  if (!schema || typeof schema !== 'object') return '';
  if (schema.$ref) return typeOf(resolve(schema.$ref, defs), defs);
  if ('const' in schema) return `${code(schema.const)} exactly`;
  if (schema.enum) return `one of ${schema.enum.map(code).join(', ')}`;
  if (schema.type === 'array') return `list of ${typeOf(schema.items, defs) || 'values'}`;
  if (schema.oneOf || schema.anyOf) return (schema.oneOf ?? schema.anyOf).map((s) => typeOf(s, defs)).filter(Boolean).join(' or ');
  return Array.isArray(schema.type) ? schema.type.join(' or ') : (schema.type ?? '');
};

const resolve = (ref, defs) => defs[ref.replace(/^#\/(\$defs|definitions)\//, '')] ?? {};

/** What a value must be, beyond its type. */
export const limitsOf = (schema) => {
  const limits = [];
  if (schema.pattern) limits.push(`matches ${code(schema.pattern)}`);
  if (schema.minLength !== undefined) limits.push(`at least ${plural(schema.minLength, 'character')}`);
  if (schema.maxLength !== undefined) limits.push(`at most ${plural(schema.maxLength, 'character')}`);
  if (schema.minimum !== undefined) limits.push(`at least ${schema.minimum}`);
  if (schema.maximum !== undefined) limits.push(`at most ${schema.maximum}`);
  if (schema.minItems !== undefined) limits.push(`at least ${plural(schema.minItems, 'item')}`);
  if (schema.maxItems !== undefined) limits.push(`at most ${plural(schema.maxItems, 'item')}`);
  if (schema.uniqueItems) limits.push('no repeats');
  if (schema.format) limits.push(`a ${schema.format}`);
  if (schema.default !== undefined) limits.push(`defaults to ${code(schema.default)}`);
  return limits.length ? `${limits.join('; ').replace(/^./, (c) => c.toUpperCase())}.` : '';
};

/** One row per field, nested objects and lists of objects flattened into dotted paths. */
export const rows = (schema, defs, path = '', depth = 0) => {
  const found = [];
  const required = new Set(schema.required ?? []);
  for (const [name, raw] of Object.entries(schema.properties ?? {})) {
    if (name === '$schema') continue;
    const field = raw.$ref ? { ...resolve(raw.$ref, defs), ...raw } : raw;
    const at = path ? `${path}.${name}` : name;
    found.push({ path: at, type: typeOf(field, defs), required: required.has(name), limits: limitsOf(field), description: field.description ?? '' });
    if (depth > 4) continue;
    const inner = field.type === 'array' ? (field.items?.$ref ? resolve(field.items.$ref, defs) : field.items) : field;
    if (inner?.properties) found.push(...rows(inner, defs, field.type === 'array' ? `${at}[]` : at, depth + 1));
  }
  return found;
};

/** A reference page for one schema, as Markdown. */
export const page = ({ title, intro, file }, schema) => {
  const defs = schema.$defs ?? schema.definitions ?? {};
  const fields = rows(schema, defs)
    .map((r) => {
      const head = [`**\`${r.path}\`**`, cell(r.type), r.required ? '**required**' : 'optional'].filter(Boolean).join(' · ');
      const body = cell([r.description, r.limits].filter(Boolean).join(' '));
      return body ? `${head}\\\n${body}` : head;
    })
    .join('\n\n');
  return `---
title: ${title}
description: ${JSON.stringify(intro.replace(/`/g, ''))}
status: beta
sidebar:
  badge: { text: Generated, variant: default }
---

${cell(schema.description) || intro}

Schema id \`${schema.$id}\`. Generated from \`${file}\` in AUGUR's repository.

## Fields

${fields}
`;
};

/** The deployment settings page: one row per setting a deployment's .env can hold. */
export const settingsPage = (schema) => {
  const required = new Set(schema.required ?? []);
  const own = Object.entries(schema.properties ?? {}).filter(([, s]) => !s['x-internal']);
  const row = ([name, s]) =>
    `| \`${name}\` | ${required.has(name) ? 'Yes' : ''} | ${s.writeOnly ? 'Yes' : ''} | ${cell([s.description ?? '', limitsOf(s)].filter(Boolean).join(' '))} |`;
  const patterns = Object.entries(schema.patternProperties ?? {}).map(([p, s]) => `| ${code(p)} | ${s.writeOnly ? 'Yes' : ''} | ${cell(s.description ?? '')} |`);
  return `---
title: Deployment settings
description: Every setting a deployment can put in its .env file.
status: beta
sidebar:
  badge: { text: Generated, variant: default }
---

Every setting a deployment can put in \`infra/deploy/.env\`. **Secret** settings are never shown again once
set; the install preflight can generate the ones nobody needs to know. Generated from
\`infra/deploy/settings.schema.json\` in AUGUR's repository.

| Setting | Required | Secret | What it is |
| --- | --- | --- | --- |
${own.map(row).join('\n')}
${patterns.length ? `\n## Settings named by pattern\n\n| Name | Secret | What it is |\n| --- | --- | --- |\n${patterns.join('\n')}\n` : ''}`;
};

if (import.meta.url === `file://${process.argv[1]}`) {
  rmSync(out, { recursive: true, force: true });
  mkdirSync(out, { recursive: true });
  const read = (file) => JSON.parse(readFileSync(repo(file), 'utf8'));
  SCHEMAS.forEach((s, i) => {
    writeFileSync(`${out}${s.slug}.md`, page(s, read(s.file)).replace('sidebar:\n', `sidebar:\n  order: ${i + 1}\n`));
  });
  writeFileSync(`${out}settings.md`, settingsPage(read('infra/deploy/settings.schema.json')).replace('sidebar:\n', `sidebar:\n  order: ${SCHEMAS.length + 1}\n`));
  console.log(`Wrote ${SCHEMAS.length + 1} reference pages from AUGUR's schemas.`);
}
